mapper.select:
select t.msg,t.phone_jpg,t.phone_jpg phoneJpg,t.pa_num,t.pa_num paNum,t.machine_code,t.machine_code
machineCode,t.car_num,t.car_num carNum,t.remark,t.status_cd,t.status_cd statusCd,t.auth_id,t.auth_id
authId,t.machine_name,t.machine_name machineName,t.car_type,t.car_type carType,t.machine_id,t.machine_id
machineId,t.pa_id,t.pa_id paId,t.state,t.community_id,t.community_id communityId
from car_inout_temp_auth t
where 1 =1

    and t.msg= #{msg}


    and t.phone_jpg= #{phoneJpg}


    and t.pa_num= #{paNum}


    and t.machine_code= #{machineCode}


    and t.car_num= #{carNum}


    and t.remark= #{remark}


    and t.status_cd= #{statusCd}


    and t.auth_id= #{authId}


    and t.machine_name= #{machineName}


    and t.car_type= #{carType}


    and t.machine_id= #{machineId}


    and t.pa_id= #{paId}


    and t.state= #{state}


    and t.community_id= #{communityId}

order by t.create_time desc

    limit #{page}, #{row}

